  type StepLayoutStep,
} from "@procertus-ui/ui";

export type OnboardingFloatingStepsNavProps = {
  steps: StepLayoutStep[];
  activeStep: number;
  onStepChange: (index: number) => void;
  interactive?: boolean;
  showDescriptions?: boolean;
  /** Optional Tailwind overrides for the desktop floating aside. */
  className?: string;
};

/**
 * Desktop: fixed vertical {@link StepLayoutStepper}.
 * Narrow viewports: step list is hidden behind a trailing control (icon + “current / total”)
 * that opens a side sheet panel.
 */
export function OnboardingFloatingStepsNav({
  steps,
  activeStep,
  onStepChange,
  interactive = true,
  showDescriptions = false,
  className,
}: OnboardingFloatingStepsNavProps) {
  const [sheetOpen, setSheetOpen] = useState(false);

  const total = steps.length;
  const current = total === 0 ? 0 : Math.min(activeStep + 1, total);

  if (total === 0) {
    return null;
  }

  const handleMobileNavigate = (index: number) => {
    onStepChange(index);
    setSheetOpen(false);
  };

  return (
    <>
      <aside
        className={cn(
          "pointer-events-auto fixed top-44 z-40 hidden max-h-[min(34rem,calc(100svh-11rem))] w-[min(18rem,calc(100vw-2rem))] shrink-0 overflow-y-auto overscroll-contain rounded-xl border border-border bg-card/95 p-component shadow-proc-xs backdrop-blur-sm end-6 md:block",
          className,
        )}
        aria-label="Traject steps"
      >
        <StepLayoutStepper
          className="w-full !max-w-none"
          steps={steps}
          activeStep={activeStep}
          interactive={interactive}
          orientation="vertical"
          showDescriptions={showDescriptions}
          onStepChange={onStepChange}
        />
      </aside>

      <div className="pointer-events-none fixed end-4 bottom-28 z-40 md:hidden">
        <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
          <Button
            type="button"
            variant="secondary"
            size="sm"
            className="pointer-events-auto h-11 gap-2 rounded-full border border-border bg-card/95 pr-4 pl-3 shadow-proc-xs backdrop-blur-sm min-[420px]:h-10"
            onClick={() => setSheetOpen(true)}
            aria-expanded={sheetOpen}
            aria-haspopup="dialog"
          >
            <ListOrdered className="size-4 shrink-0 text-muted-foreground" aria-hidden />
            <span aria-hidden className="tabular-nums text-sm font-medium tracking-tight text-foreground">
              {current}
              <span className="text-muted-foreground">/{total}</span>
            </span>
            <span className="sr-only">
              Open step list. Step {current} of {total}.
            </span>
          </Button>
          <SheetContent
            side="right"
            showCloseButton
            className="flex max-h-[100dvh] flex-col [--sheet-side-width:min(22rem,calc(100vw-1rem))]"
          >
            <SheetHeader className="shrink-0">
              <SheetTitle>Steps</SheetTitle>
            </SheetHeader>
            <SheetBody className="min-h-0 flex-1">
              <StepLayoutStepper
                className="w-full !max-w-none"
                steps={steps}
                activeStep={activeStep}
                interactive={interactive}
                orientation="vertical"
                showDescriptions={showDescriptions}
                onStepChange={handleMobileNavigate}
              />
            </SheetBody>
          </SheetContent>
        </Sheet>
      </div>
    </>
  );
}

